describe('Login Form Validation', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display error messages when required fields are empty', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Verify error container is visible
    cy.get('[data-testid="error"]').should('be.visible');

    // Verify error message is displayed for empty username
    cy.get('[data-testid="error"]').should('contain', 'Username is required');

    // Verify error container is visible
    cy.get('[data-testid="error"]').should('be.visible');

    // Verify error message is displayed for empty password
    cy.get('[data-testid="error"]').should('contain', 'Password is required');
  });

  it('should display error messages when only one required field is filled', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Fill in only the username field
    cy.get('[data-testid="username-input"]').type('standard_user');

    // Verify error container is visible
    cy.get('[data-testid="error"]').should('be.visible');

    // Verify error message is displayed for empty password
    cy.get('[data-testid="error"]').should('contain', 'Password is required');

    // Verify error container is visible
    cy.get('[data-testid="error"]').should('be.visible');

    // Verify error message is displayed for empty username
    cy.get('[data-testid="error"]').should('contain', 'Username is required');
  });
});
